Title: Response
Link: https://assemblyai.com/docs/speech-understanding/speaker-identification#response
Page: speech-understanding/speaker-identification
Content: ### Response

The Speaker Identification API returns a modified version of your transcript with updated speaker labels in the `utterances` key.

```json expandable theme={null}
{
  "speech_understanding": {
    "request": {
      "speaker_identification": {
        "speaker_type": "name",
        "speakers": [{"name": "Michel Martin"}, {"name": "Peter DeCarlo"}]
      }
    },
    "response": {
      "speaker_identification": {
        "mapping": {
          "A": "Michel Martin",
          "B": "Peter DeCarlo"
        },
        "status": "success"
      }
    }
  },
  "utterances": [
    {
      "speaker": "Michel Martin",
      "text": "Smoke from hundreds of wildfires in Canada is triggering air quality alerts...",
      "start": 240,
      "end": 26560,
      "confidence": 0.9815734,
      "words": [
        {
          "text": "Smoke",
          "start": 240,
          "end": 640,
          "confidence": 0.90152997,
          "speaker": "Michel Martin"
        }
        // ... more words
      ]
    }
    // ... more utterances
  ]
}
```

Title: Translation with speaker labels
Link: https://assemblyai.com/docs/speech-understanding/translation#translation-with-speaker-labels
Page: speech-understanding/translation
Content: ## Translation with speaker labels

When you use Translation with [Speaker Labels](/pre-recorded-audio/label-speakers), you can get translated text for each individual utterance by setting `match_original_utterance` to `true`. This is useful for creating speaker-specific subtitles or analyzing conversations in multiple languages while preserving speaker attribution.

<Tabs groupId="language">
  <Tab language="python" title="Python" default>
    ```python expandable theme={null}
    import requests
    import time

    base_url = "https://api.assemblyai.com"

    headers = {
      "authorization": "YOUR_API_KEY"
    }

    audio_url = "https://assembly.ai/wildfires.mp3"

    # Configure transcription with translation and speaker labels
    data = {
      "audio_url": audio_url,
      "language_detection": True,
      "speaker_labels": True,  # Enable speaker labels
      "speech_understanding": {
        "request": {
          "translation": {
            "target_languages": ["es"],
            "match_original_utterance": True,  # Get translated text per utterance
            "formal": True
          }
        }
      }
    }

    # Submit transcription request
    response = requests.post(base_url + "/v2/transcript", headers=headers, json=data)
    transcript_id = response.json()["id"]
    polling_endpoint = base_url + f"/v2/transcript/{transcript_id}"

    # Poll transcription results
    while True:
      transcript = requests.get(polling_endpoint, headers=headers).json()

      if transcript["status"] == "completed":
        break

      elif transcript["status"] == "error":
        raise RuntimeError(f"Transcription failed: {transcript['error']}")

      else:
        time.sleep(3)

    # Access translated utterances
    for utterance in transcript["utterances"]:
      print(f"Speaker {utterance['speaker']}:")
      print(f"  Original: {utterance['text'][:100]}...")
      print(f"  Spanish: {utterance['translated_texts']['es'][:100]}...")
      print()
    ```
  </Tab>

  <Tab language="javascript" title="JavaScript" default>
    ```javascript expandable theme={null}
    import fetch from "node-fetch";

    const baseUrl = "https://api.assemblyai.com";
    const headers = {
      authorization: "YOUR_API_KEY",
    };

    const audioUrl = "https://assembly.ai/wildfires.mp3";

    // Configure transcription with translation and speaker labels
    const data = {
      audio_url: audioUrl,
      language_detection: true,
      speaker_labels: true, // Enable speaker labels
      speech_understanding: {
        request: {
          translation: {
            target_languages: ["es"],
            match_original_utterance: true, // Get translated text per utterance
            formal: true,
          },
        },
      },
    };

    async function transcribeWithTranslatedUtterances() {
      const response = await fetch(`${baseUrl}/v2/transcript`, {
        method: "POST",
        headers: {
          ...headers,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(data),
      });

      const transcript = await response.json();
      const transcriptId = transcript.id;
      const pollingEndpoint = `${baseUrl}/v2/transcript/${transcriptId}`;

      // Poll transcription results
      while (true) {
        const pollingResponse = await fetch(pollingEndpoint, { headers });
        const transcriptResult = await pollingResponse.json();

        if (transcriptResult.status === "completed") {
          // Access translated utterances
          for (const utterance of transcriptResult.utterances) {
            console.log(`Speaker ${utterance.speaker}:`);
            console.log(`  Original: ${utterance.text.substring(0, 100)}...`);
            console.log(
              `  Spanish: ${utterance.translated_texts.es.substring(0, 100)}...`
            );
            console.log();
          }
          break;
        } else if (transcriptResult.status === "error") {
          throw new Error(`Transcription failed: ${transcriptResult.error}`);
        } else {
          await new Promise((resolve) => setTimeout(resolve, 3000));
        }
      }
    }

    transcribeWithTranslatedUtterances();
    ```
  </Tab>
</Tabs>

**Example response:**

Each utterance in the `utterances` array includes a `translated_texts` object with the translation for that specific speaker's utterance:

```json expandable theme={null}
{
  "utterances": [
    {
      "speaker": "A",
      "text": "Smoke from hundreds of wildfires in Canada is triggering air quality alerts...",
      "confidence": 0.9815734,
      "start": 240,
      "end": 26560,
      "words": [...],
      "translated_texts": {
        "es": "El humo de cientos de incendios forestales en Canadá está activando alertas de calidad del aire..."
      }
    },
    {
      "speaker": "B",
      "text": "Good morning.",
      "confidence": 0.98217773,
      "start": 28060,
      "end": 28620,
      "words": [...],
      "translated_texts": {
        "es": "Buenos días."
      }
    }
  ]
}
```

Title: Identify speakers by name
Link: https://assemblyai.com/docs/pre-recorded-audio/label-speakers#identify-speakers-by-name
Page: pre-recorded-audio/label-speakers
Content: ### Identify speakers by name

Speaker Diarization assigns generic labels like "Speaker A" and "Speaker B" to each speaker. If you want to replace these labels with actual names or roles, you can use Speaker Identification to transform your transcript.

**Before Speaker Identification:**

```txt theme={null}
Speaker A: Good morning, and welcome to the show.
Speaker B: Thanks for having me.
```

**After Speaker Identification:**

```txt theme={null}
Michel Martin: Good morning, and welcome to the show.
Peter DeCarlo: Thanks for having me.
```

The following example shows how to transcribe audio with Speaker Diarization and then apply Speaker Identification to replace the generic speaker labels with actual names.

<Tabs groupId="language">
  <Tab language="python" title="Python" default>
    ```python maxLines=30 expandable theme={null}
    import requests
    import time

    base_url = "https://api.assemblyai.com"

    headers = {
        "authorization": "<YOUR_API_KEY>"
    }

    audio_url = "https://assembly.ai/wildfires.mp3"

    # Configure transcript with speaker diarization and speaker identification
    data = {
        "audio_url": audio_url,
        "language_detection": True,
        "speaker_labels": True,
        "speech_understanding": {
            "request": {
                "speaker_identification": {
                    "speaker_type": "name",
                    "known_values": ["Michel Martin", "Peter DeCarlo"]
                }
            }
        }
    }

    # Submit the transcription request
    response = requests.post(base_url + "/v2/transcript", headers=headers, json=data)
    transcript_id = response.json()["id"]
    polling_endpoint = base_url + f"/v2/transcript/{transcript_id}"

    # Poll for transcription results
    while True:
        transcript = requests.get(polling_endpoint, headers=headers).json()

        if transcript["status"] == "completed":
            break
        elif transcript["status"] == "error":
            raise RuntimeError(f"Transcription failed: {transcript['error']}")
        else:
            time.sleep(3)

    # Print utterances with identified speaker names
    for utterance in transcript["utterances"]:
        print(f"{utterance['speaker']}: {utterance['text']}")
    ```
  </Tab>

  <Tab language="javascript" title="JavaScript">
    ```javascript maxLines=30 expandable theme={null}
    const baseUrl = "https://api.assemblyai.com";

    const headers = {
      authorization: "<YOUR_API_KEY>",
      "content-type": "application/json",
    };

    const audioUrl = "https://assembly.ai/wildfires.mp3";

    // Configure transcript with speaker diarization and speaker identification
    const data = {
      audio_url: audioUrl,
      language_detection: true,
      speaker_labels: true,
      speech_understanding: {
        request: {
          speaker_identification: {
            speaker_type: "name",
            known_values: ["Michel Martin", "Peter DeCarlo"],
          },
        },
      },
    };

    async function main() {
      // Submit the transcription request
      const response = await fetch(`${baseUrl}/v2/transcript`, {
        method: "POST",
        headers: headers,
        body: JSON.stringify(data),
      });
      if (!response.ok) throw new Error(`Error: ${response.status}`);

      const { id: transcriptId } = await response.json();
      const pollingEndpoint = `${baseUrl}/v2/transcript/${transcriptId}`;

      // Poll for transcription results
      while (true) {
        const pollingResponse = await fetch(pollingEndpoint, { headers });
        if (!pollingResponse.ok) throw new Error(`Error: ${pollingResponse.status}`);
        const transcript = await pollingResponse.json();

        if (transcript.status === "completed") {
          // Print utterances with identified speaker names
          for (const utterance of transcript.utterances) {
            console.log(`${utterance.speaker}: ${utterance.text}`);
          }
          break;
        } else if (transcript.status === "error") {
          throw new Error(`Transcription failed: ${transcript.error}`);
        } else {
          await new Promise((resolve) => setTimeout(resolve, 3000));
        }
      }
    }

    main().catch(console.error);
    ```
  </Tab>
</Tabs>

For more details on Speaker Identification, including how to identify speakers by role and how to apply it to existing transcripts, see the [Speaker Identification guide](/speech-understanding/speaker-identification).

